            Id=id;Type=type;AvailableHeadcount=availableHeadcount;Authority=authority??throw new ArgumentNullException(nameof(authority));CityId=cityId;InstitutionId=institutionId;ObligationOrContractId=obligationOrContractId??string.Empty;IsActive=active;
        }
        public RecruitmentSourceId Id{get;}public RecruitmentType Type{get;}public long AvailableHeadcount{get;private set;}public RecruitmentAuthorityReference Authority{get;}public CityId? CityId{get;}public CityBuildingId? InstitutionId{get;}public string ObligationOrContractId{get;}public bool IsActive{get;private set;}public bool CanConsume(long quantity)=>IsActive&&quantity>0&&AvailableHeadcount>=quantity;
        public void Consume(long quantity){if(!IsActive||quantity<=0||AvailableHeadcount<quantity)throw new InvalidOperationException("Recruitment source cannot provide the requested headcount.");AvailableHeadcount-=quantity;}public void Deactivate()=>IsActive=false;
    }

