        private readonly SortedDictionary<TradeGoodId,TradeGoodStock> _items=new SortedDictionary<TradeGoodId,TradeGoodStock>();public IReadOnlyCollection<TradeGoodStock> OrderedGoods=>_items.Values;public long QuantityOf(TradeGoodId id)=>_items.TryGetValue(id,out var x)?x.Quantity.Value:0;public bool CanAdd(TradeGoodId id,long quantity){if(!id.IsValid||quantity<=0)return false;try{checked{var unused=QuantityOf(id)+quantity;return unused>=0;}}catch(OverflowException){return false;}}public void AddInitial(TradeGoodId id,long quantity){if(!id.IsValid||quantity<0)throw new ArgumentOutOfRangeException(nameof(quantity));if(_items.ContainsKey(id))throw new InvalidOperationException("Duplicate Army supply good.");_items.Add(id,new TradeGoodStock(id,quantity));}private void Add(TradeGoodId id,long quantity){if(!CanAdd(id,quantity))throw new InvalidOperationException("Army supply increase is invalid.");if(!_items.TryGetValue(id,out var item)){item=new TradeGoodStock(id,0);_items.Add(id,item);}item.Quantity=new GoodsQuantity(item.Quantity.Value+quantity);}private void Remove(TradeGoodId id,long quantity){if(quantity<=0||!_items.TryGetValue(id,out var item)||item.Quantity.Value<quantity)throw new InvalidOperationException("Insufficient Army supply.");item.Quantity=new GoodsQuantity(item.Quantity.Value-quantity);}public void TransferFrom(CityStockState source,TradeGoodId id,long quantity){if(source==null)throw new ArgumentNullException(nameof(source));if(source.QuantityOf(id)<quantity||!CanAdd(id,quantity))throw new InvalidOperationException("City-to-Army supply transfer cannot complete atomically.");source.Remove(id,quantity);Add(id,quantity);}public void TransferFrom(CaravanCargoState source,TradeGoodId id,long quantity){if(source==null)throw new ArgumentNullException(nameof(source));if(source.QuantityOf(id)<quantity||!CanAdd(id,quantity))throw new InvalidOperationException("Caravan-to-Army supply transfer cannot complete atomically.");source.Remove(id,quantity);Add(id,quanti