    public sealed class SupplyRequirementState
    {
        public SupplyRequirementState(TradeGoodId goodId,SupplyPurpose purpose,long requiredQuantity){if(!goodId.IsValid)throw new ArgumentException(nameof(goodId));if(!Enum.IsDefined(typeof(SupplyPurpose),purpose))throw new ArgumentOutOfRangeException(nameof(purpose));if(requiredQuantity<0)throw new ArgumentOutOfRangeException(nameof(requiredQuantity));GoodId=goodId;Purpose=purpose;RequiredQuantity=requiredQuantity;}public TradeGoodId GoodId{get;}public SupplyPurpose Purpose{get;}public long RequiredQuantity{get;}public SupplyCondition Assess(ArmySupplyInventory inventory){var available=inventory.QuantityOf(GoodId);if(RequiredQuantity==0)return SupplyCondition.NotRequired;if(available==0)return SupplyCondition.Exhausted;return available<RequiredQuantity?SupplyCondition.Insufficient:SupplyCondition.Supplied;}
    }

