    public sealed class ArmyReadinessProjection
    {public ArmyReadinessProjection(ArmyState army){if(army==null)throw new ArgumentNullException(nameof(army));Morale=army.Morale.Assessment;Fatigue=army.Fatigue.Assessment;Discipline=army.Discipline.Assessment;var list=new List<SupplyCondition>();foreach(var x in army.OrderedSupplyRequirements)list.Add(x.Assess(army.Supply));SupplyConditions=list;}public MoraleAssessment Morale{get;}public FatigueAssessment Fatigue{get;}public DisciplineAssessment Discipline{get;}public IReadOnlyList<SupplyCondition> SupplyConditions{get;}}
    public sealed class ArmySupplyConsumptionResult{public ArmySupplyConsumptionResult(long requested,long consumed){Requested=requested;Consumed=consumed;Shortage=requested-consumed;}public long Requested{get;}public long Consumed{get;}public long Shortage{get;}public bool HasShortage=>Shortage>0;}
}
